+use std::collections::HashSet;
+
+const LOWER: &str = "abcdefghijklmnopqrstuvwxyz";
+const UPPER: &str = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
+const DIGITS: &str = "0123456789";
+const HEX_LOWER: &str = "0123456789abcdef";
+const HEX_UPPER: &str = "0123456789ABCDEF";
+const SYMBOLS: &str = " !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";
+
+pub fn expand_charset_spec(spec: &str) -> Result<Vec<char>, String> {
+    let mut out = String::new();
+    for token in spec.chars() {
+        match token {
+            'l' => out.push_str(LOWER),
+            'u' => out.push_str(UPPER),
+            'd' => out.push_str(DIGITS),
+            'h' => out.push_str(HEX_LOWER),
+            'H' => out.push_str(HEX_UPPER),
+            's' => out.push_str(SYMBOLS),
+            other => return Err(format!("Unknown charset option '{other}'")),
+        }
+    }
+
+    Ok(dedup_charset(&out))
+}
+
+pub fn dedup_charset(source: &str) -> Vec<char> {
+    let mut seen = HashSet::new();
+    let mut charset = Vec::new();
+    for ch in source.chars() {
+        if seen.insert(ch) {
+            charset.push(ch);
+        }
+    }
+    charset
+}
+
+pub fn charset_contains_only(candidate: &str, charset: &[char]) -> bool {
+    let allowed: HashSet<char> = charset.iter().copied().collect();
+    candidate.chars().all(|ch| allowed.contains(&ch))
+}
+
+pub fn total_passwords(charset_len: usize, length: usize) -> u128 {
+    let mut total = 1u128;
+    for _ in 0..length {
+        total = total.saturating_mul(charset_len as u128);
+    }
+    total
+}
+
+pub fn password_to_index(password: &str, charset: &[char]) -> Option<u128> {
+    let base = charset.len() as u128;
+    let mut index = 0u128;
+    for ch in password.chars() {
+        let digit = charset.iter().position(|value| *value == ch)? as u128;
+        index = index.checked_mul(base)?.checked_add(digit)?;
+    }
+    Some(index)
+}
+
+pub fn index_to_password(mut index: u128, length: usize, charset: &[char]) -> String {
+    assert!(!charset.is_empty(), "charset non empty");
+
+    let base = charset.len() as u128;
+    let mut chars = vec![charset[0]; length];
+    for slot in (0..length).rev() {
+        let digit = (index % base) as usize;
+        chars[slot] = charset[digit];
+        index /= base;
+    }
+    chars.into_iter().collect()
+}
