+use std::fmt;
+use std::io::{Cursor, Read};
+use std::sync::Arc;
+
+use zip::result::ZipError;
+use zip::read::ZipArchive;
+
+#[derive(Clone)]
+pub struct ArchiveSpec {
+    data: Arc<[u8]>,
+    pub file_number: usize,
+    pub file_name: String,
+    pub encryption: EncryptionKind,
+}
+
+#[derive(Clone, Copy, Debug, Eq, PartialEq)]
+pub enum EncryptionKind {
+    ZipCrypto,
+    Aes128,
+    Aes192,
+    Aes256,
+}
+
+impl fmt::Display for EncryptionKind {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        match self {
+            Self::ZipCrypto => f.write_str("ZipCrypto"),
+            Self::Aes128 => f.write_str("AES128"),
+            Self::Aes192 => f.write_str("AES192"),
+            Self::Aes256 => f.write_str("AES256"),
+        }
+    }
+}
+
+impl ArchiveSpec {
+    pub fn load(path: &std::path::Path, file_number: usize) -> Result<Self, ArchiveLoadError> {
+        let data = std::fs::read(path).map_err(ArchiveLoadError::Io)?;
+        let data: Arc<[u8]> = Arc::from(data);
+        let mut archive = ZipArchive::new(Cursor::new(data.clone()))
+            .map_err(ArchiveLoadError::InvalidArchive)?;
+
+        let file = archive
+            .by_index_raw(file_number)
+            .map_err(|err| match err {
+                ZipError::FileNotFound => ArchiveLoadError::FileNumberNotFound(file_number),
+                other => ArchiveLoadError::InvalidArchive(other),
+            })?;
+
+        if !file.encrypted() {
+            return Err(ArchiveLoadError::NotEncrypted {
+                file_number,
+                file_name: file.name().to_owned(),
+            });
+        }
+
+        Ok(Self {
+            data,
+            file_number,
+            file_name: file.name().to_owned(),
+            encryption: detect_encryption_kind(&file),
+        })
+    }
+
+    pub fn password_matches(&self, password: &str) -> bool {
+        let mut archive = match ZipArchive::new(Cursor::new(self.data.clone())) {
+            Ok(archive) => archive,
+            Err(_) => return false,
+        };
+
+        let mut file = match archive.by_index_decrypt(self.file_number, password.as_bytes()) {
+            Ok(file) => file,
+            Err(_) => return false,
+        };
+
+        let mut sink = Vec::new();
+        file.read_to_end(&mut sink).is_ok()
+    }
+}
+
+#[derive(Debug)]
+pub enum ArchiveLoadError {
+    Io(std::io::Error),
+    InvalidArchive(ZipError),
+    FileNumberNotFound(usize),
+    NotEncrypted { file_number: usize, file_name: String },
+}
+
+fn detect_encryption_kind(file: &zip::read::ZipFile<'_, Cursor<Arc<[u8]>>>) -> EncryptionKind {
+    if let Some(mode) = file.aes_mode() {
+        match mode {
+            zip::AesMode::Aes128 => EncryptionKind::Aes128,
+            zip::AesMode::Aes192 => EncryptionKind::Aes192,
+            zip::AesMode::Aes256 => EncryptionKind::Aes256,
+        }
+    } else {
+        EncryptionKind::ZipCrypto
+    }
+}
