+fn search_dictionary(archive: &ArchiveSpec, passwords: &[String], workers: usize) -> Option<String> {
+    let found = Arc::new(AtomicBool::new(false));
+    let answer = Arc::new(Mutex::new(None));
+    let passwords = Arc::new(passwords.to_vec());
+
