+fn search_bruteforce(
+    archive: &ArchiveSpec,
+    charset: &[char],
+    min_len: usize,
+    max_len: usize,
+    starting_password: Option<&str>,
+    workers: usize,
+    stdout_is_tty: bool,
+    start_time: Instant,
+) -> Option<String> {
+    let found = Arc::new(AtomicBool::new(false));
+    let answer = Arc::new(Mutex::new(None));
+    let processed = Arc::new(AtomicU64::new(0));
+    let last_password = Arc::new(Mutex::new(None));
+
+    let stages: Vec<Stage> = (min_len..=max_len)
+        .filter_map(|length| {
+            let start_index = match starting_password {
+                Some(candidate) if candidate.len() > length => return None,
+                Some(candidate) if candidate.len() == length => password_to_index(candidate, charset)?,
+                _ => 0,
+            };
+            let total = total_passwords(charset.len(), length);
+            if start_index >= total {
+                None
+            } else {
+                Some(Stage {
+                    length,
+                    total,
+                    start_index,
+                })
+            }
+        })
+        .collect();
+
+    let total_work: u128 = stages.iter().map(|stage| stage.total - stage.start_index).sum();
+
+    let progress_stop = Arc::new(AtomicBool::new(false));
+    let progress_thread = if stdout_is_tty {
+        let processed = Arc::clone(&processed);
+        let progress_stop = Arc::clone(&progress_stop);
+        let last_password = Arc::clone(&last_password);
+        Some(thread::spawn(move || {
+            while !progress_stop.load(Ordering::Relaxed) {
+                render_progress(
+                    start_time.elapsed(),
+                    processed.load(Ordering::Relaxed) as u128,
+                    total_work,
+                    last_password.lock().expect("last password lock").clone(),
+                );
+                thread::sleep(Duration::from_millis(125));
+            }
+        }))
+    } else {
+        None
+    };
+
+    thread::scope(|scope| {
+        for stage in &stages {
+            if stdout_is_tty {
+                let generated_before: u128 = stages
+                    .iter()
+                    .take_while(|other| other.length < stage.length)
+                    .map(|other| other.total - other.start_index)
+                    .sum();
+                if generated_before == 0 {
+                    println!(
+                        "Starting search space for password length {} ({} possibilities)",
+                        stage.length,
+                        stage.total - stage.start_index
+                    );
+                } else {
+                    println!(
+                        "Starting search space for password length {} ({} possibilities) ({} passwords generated so far)",
+                        stage.length,
+                        stage.total - stage.start_index,
+                        generated_before
+                    );
+                }
+            }
+
+            for worker_id in 0..workers {
+                let archive = archive.clone();
+                let found = Arc::clone(&found);
+                let answer = Arc::clone(&answer);
+                let processed = Arc::clone(&processed);
+                let last_password = Arc::clone(&last_password);
+                let charset = charset.to_vec();
+                let stage = stage.clone();
+
+                let builder = thread::Builder::new().name(format!("worker-{}", worker_id + 1));
+                let handle = builder
+                    .spawn_scoped(scope, move || {
+                        let mut index = stage.start_index + worker_id as u128;
+                        while index < stage.total && !found.load(Ordering::Relaxed) {
+                            let candidate = index_to_password(index, stage.length, &charset);
+                            *last_password.lock().expect("last password lock") = Some(candidate.clone());
+                            if archive.password_matches(&candidate) {
+                                found.store(true, Ordering::Relaxed);
+                                *answer.lock().expect("answer lock") = Some(candidate);
+                                break;
+                            }
+                            processed.fetch_add(1, Ordering::Relaxed);
+                            index += workers as u128;
+                        }
+                    })
+                    .expect("spawn worker");
+                let _ = handle;
+            }
+        }
+    });
+
+    progress_stop.store(true, Ordering::Relaxed);
+    if let Some(thread) = progress_thread {
+        let _ = thread.join();
+    }
+    if stdout_is_tty {
+        clear_progress_line();
+    }
+
+    answer.lock().expect("answer lock").clone()
+}
+
+fn render_progress(
+    elapsed: Duration,
+    processed: u128,
+    total: u128,
+    last_password: Option<String>,
+) {
+    let bar_len = 41usize;
+    let filled = if total == 0 {
+        bar_len
+    } else {
+        ((processed.min(total) * bar_len as u128) / total) as usize
+    };
+    let bar = format!(
+        "{}{}",
+        "█".repeat(filled),
+        "░".repeat(bar_len.saturating_sub(filled))
+    );
+    let elapsed_secs = elapsed.as_secs_f64();
+    let throughput = if elapsed_secs == 0.0 {
+        0.0
+    } else {
+        processed as f64 / elapsed_secs
+    };
+    let remaining = total.saturating_sub(processed);
+    let eta = if throughput <= 0.0 {
+        0
+    } else {
+        (remaining as f64 / throughput) as u64
+    };
+
+    print!(
+        "\r\x1b[2K[{}] {} {}/{} throughput:{}/s (eta:{}s)",
+        format_clock(elapsed),
+        bar,
+        processed,
+        total,
+        format_rate(throughput),
+        eta
+    );
+    if let Some(password) = last_password {
+        print!(" Last password processed:{password}");
+    }
+    let _ = io::stdout().flush();
+}
+
+fn clear_progress_line() {
+    print!("\r\x1b[2K");
+    let _ = io::stdout().flush();
+}
+
+fn format_clock(duration: Duration) -> String {
+    let total = duration.as_secs();
+    let hours = total / 3600;
+    let minutes = (total / 60) % 60;
+    let seconds = total % 60;
+    format!("{hours:02}:{minutes:02}:{seconds:02}")
+}
+
+fn format_rate(rate: f64) -> String {
+    if rate >= 1_000_000.0 {
+        format!("{:.1}M", rate / 1_000_000.0)
+    } else if rate >= 1_000.0 {
+        format!("{rate:,.4}")
+    } else {
+        format!("{:.0}", rate)
+    }
+}
+
+#[derive(Clone)]
+struct Stage {
+    length: usize,
+    total: u128,
+    start_index: u128,
+}
+
+#[derive(Debug)]
+enum AppError {
+    CliArgument(String),
+    InvalidZip(String),
+    FileNumberNotFound(usize),
+    Execution(String),
+}
+
+impl std::fmt::Display for AppError {
+    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
+        match self {
+            Self::CliArgument(message) => write!(f, "CLI argument error - \"{message}\""),
+            Self::InvalidZip(message) => write!(f, "Invalid zip file error - {message}"),
+            Self::FileNumberNotFound(file_number) => {
+                write!(f, "File number not found within archive error - '{file_number}'")
+            }
+            Self::Execution(message) => f.write_str(message),
+        }
+    }
+}
+
+impl From<ArchiveLoadError> for AppError {
+    fn from(value: ArchiveLoadError) -> Self {
+        match value {
+            ArchiveLoadError::Io(err) => Self::Execution(err.to_string()),
+            ArchiveLoadError::InvalidArchive(err) => Self::InvalidZip(err.to_string()),
+            ArchiveLoadError::FileNumberNotFound(file_number) => Self::FileNumberNotFound(file_number),
+            ArchiveLoadError::NotEncrypted {
+                file_number,
+                file_name,
+            } => Self::InvalidZip(format!(
+                "the selected file in the archive is not encrypted (file_number:{file_number} file_name:{file_name})"
+            )),
+        }
+    }
+}
